/* Generates portal/data/workspace-config.js — the ONE fully Studio-managed
 * content file (it did not exist before Studio; its header says so). Unlike
 * every other adapter, this is whole-file generation, not reconciliation:
 * there are no hand-written comments to preserve because Studio owns the
 * file. The helper functions below the data are fixed boilerplate consumed
 * by terminal-app.js / code-editor-app.js at runtime.
 */

const HEADER = `/* SwayForm Learning Portal — student workspace configuration.
 *
 * MANAGED BY STUDIO: this entire file is regenerated by the SwayForm
 * Learning Portal Studio (studio/ — local dev tool) on every Studio save,
 * so hand edits here WILL be overwritten. Custom behavior belongs in the
 * consuming apps (terminal-app.js, code-editor-app.js), not in this file.
 *
 * Terminals contract (enforced by terminal-app.js):
 *   min      — a student can never close below this many terminals (>= 1)
 *   default  — how many terminals a fresh workspace opens with
 *   max      — the + button disables at this many
 *   allowCreate — whether students may open new terminals at all
 *   namePrefix  — display name stem ("Shell" -> Shell 1, Shell 2, ...)
 *
 * perActivity[activityId] may override: terminals (same shape), plus
 *   readOnlyFiles: [workspace paths students can view but not edit]
 *   defaultOpenFile: workspace path opened when the editor mounts
 */
`;

const HELPERS = `
/** Effective terminal config for an activity (global defaults + override). */
export function terminalConfigFor(activityId) {
  const override = (WORKSPACE_CONFIG.perActivity[activityId] || {}).terminals || {};
  const t = { ...WORKSPACE_CONFIG.terminals, ...override };
  t.min = Math.max(1, t.min | 0 || 1);
  t.max = Math.max(t.min, t.max | 0 || t.min);
  t.default = Math.min(t.max, Math.max(t.min, t.default | 0 || t.min));
  return t;
}

/** Whether a workspace file is read-only for the given activity. */
export function isReadOnlyFile(activityId, path) {
  if (WORKSPACE_CONFIG.readOnlyFiles.includes(path)) return true;
  const per = WORKSPACE_CONFIG.perActivity[activityId];
  return !!(per && per.readOnlyFiles && per.readOnlyFiles.includes(path));
}

/** Default file the Code Editor opens for an activity (falls back to the
 * activity's own workspaceFile, handled by the caller). */
export function defaultOpenFileFor(activityId) {
  const per = WORKSPACE_CONFIG.perActivity[activityId];
  return (per && per.defaultOpenFile) || null;
}
`;

function literal(value, indent) {
  // Compact, stable, single-quoted JS literal printer for plain data.
  const pad = '  '.repeat(indent);
  const padIn = '  '.repeat(indent + 1);
  if (value === null) return 'null';
  if (typeof value === 'string') return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n')}'`;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    if (!value.length) return '[]';
    return `[${value.map((v) => literal(v, indent)).join(', ')}]`;
  }
  const entries = Object.entries(value).filter(([, v]) => v !== undefined);
  if (!entries.length) return '{}';
  const body = entries
    .map(([k, v]) => `${padIn}${/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(k) ? k : `'${k}'`}: ${literal(v, indent + 1)},`)
    .join('\n');
  return `{\n${body}\n${pad}}`;
}

export function generateWorkspaceConfig(config) {
  const data = {
    terminals: {
      min: config.terminals.min,
      default: config.terminals.default,
      max: config.terminals.max,
      allowCreate: config.terminals.allowCreate !== false,
      namePrefix: config.terminals.namePrefix || 'Shell',
    },
    readOnlyFiles: config.readOnlyFiles || [],
    perActivity: config.perActivity || {},
  };
  return `${HEADER}\nexport const WORKSPACE_CONFIG = ${literal(data, 0)};\n${HELPERS}`;
}
